let unmapped = configure_window(&mut diagnostics, first["id"].as_str().unwrap(), deadline)?;
if unmapped["mapped"] != false || unmapped["fullscreen"] != false {
    return Err("unmap retained fullscreen".into());
}
evidence["unmapped"] = unmapped;
